import{_ as t,c as e,o as a,a2 as i}from"./chunks/framework.B3iQLowF.js";const s=JSON.parse('{"title":"Attestation SDK - Overview | Mohanpathi Portfolio","description":"Enterprise-grade software project by Mohanpathi - System Architect & Full-Stack Engineer","frontmatter":{"layout":"doc","title":"Attestation SDK - Overview"},"headers":[],"relativePath":"docs/attestify/index.md","filePath":"docs/attestify/index.md","lastUpdated":1741638736000}');const r=t({name:"docs/attestify/index.md"},[["render",function(t,s,r,n,o,l){return a(),e("div",null,s[0]||(s[0]=[i('<h1 id="attestation-sdk" tabindex="-1">Attestation SDK <a class="header-anchor" href="#attestation-sdk" aria-label="Permalink to &quot;Attestation SDK&quot;">​</a></h1><p><strong>Managing digital payment commitments with cryptographic precision</strong><br><em>A TypeScript toolkit for secure, scalable attestation workflows</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>Attestation SDK</strong> is a powerful TypeScript library designed to manage digital payment commitments using hierarchical deterministic (HD) wallets and cryptographic attestations, adhering to the BAFT Digital Ledger Payment Commitment protocol. Whether you’re building decentralized finance applications, securing mutual agreements, or automating commitment lifecycles, this SDK provides the tools to handle it all—securely and at scale.</p><p>This project goes beyond a single library. It’s a complete ecosystem featuring:</p><ul><li><strong>Core SDK</strong>: The foundation for attestation lifecycle management and cryptographic operations.</li><li><strong>Attestify Backend</strong>: A RESTful service for user management, commitment persistence, and signature verification.</li><li><strong>Attestify CLI</strong>: A command-line interface for seamless interaction with the system.</li></ul><p>Together, they form <strong>Attestify</strong>—a robust solution for cryptographically secure mutual attestations.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>HD Wallet Integration</strong>: Supports BIP32/BIP39 standards for secure key derivation.</li><li><strong>Cryptographic Security</strong>: Uses secp256k1 for signature creation and verification.</li><li><strong>Flexible Signing</strong>: Compatible with external services like MetaMask and WalletConnect.</li><li><strong>Lifecycle Management</strong>: Handles attestation states—Initiated, Acknowledged, Effective, Discharged.</li><li><strong>Developer-Friendly</strong>: Offers configurable derivation paths, state validation, and detailed error handling.</li><li><strong>Backend Support</strong>: Integrates with a MongoDB-backed REST API for persistent workflows.</li><li><strong>CLI Automation</strong>: Simplifies attestation management with command-line tools.</li></ul><hr><h2 id="why-attestify" tabindex="-1">Why Attestify? <a class="header-anchor" href="#why-attestify" aria-label="Permalink to &quot;Why Attestify?&quot;">​</a></h2><p>In a world where digital agreements need trust and speed, Attestify solves critical challenges:</p><ul><li><strong>Trust</strong>: Multi-signature verification ensures non-repudiation and integrity.</li><li><strong>Scale</strong>: Lightweight design scales from small projects to enterprise systems.</li><li><strong>Simplicity</strong>: Abstracts complex cryptography into an easy-to-use API and CLI.</li></ul><p>Whether it’s securing payment commitments or proving agreement between parties, Attestify empowers developers to build reliable, tamper-proof systems.</p><hr><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="core-sdk" tabindex="-1">Core SDK <a class="header-anchor" href="#core-sdk" aria-label="Permalink to &quot;Core SDK&quot;">​</a></h3><p>The heart of Attestify, built in TypeScript:</p><ul><li>Manages attestation lifecycles with state transitions.</li><li>Generates and verifies signatures using industry-standard cryptography.</li><li>Integrates HD wallets for secure key management.</li></ul><h3 id="attestify-backend" tabindex="-1">Attestify Backend <a class="header-anchor" href="#attestify-backend" aria-label="Permalink to &quot;Attestify Backend&quot;">​</a></h3><p>A Node.js service with Express and MongoDB:</p><ul><li>Exposes REST APIs for user and commitment management.</li><li>Stores attestation data securely with JWT authentication.</li><li>Validates signatures and tracks commitment states.</li></ul><h3 id="attestify-cli" tabindex="-1">Attestify CLI <a class="header-anchor" href="#attestify-cli" aria-label="Permalink to &quot;Attestify CLI&quot;">​</a></h3><p>A user-friendly interface:</p><ul><li>Automates the full attestation lifecycle via commands.</li><li>Interacts with the backend for real-world workflows.</li><li>Perfect for testing, scripting, or manual operation.</li></ul><hr><h2 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get Started&quot;">​</a></h2><p>Ready to dive in? Install the SDK with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation-sdk</span></span></code></pre></div><p>Explore the <a href="./implementation">Implementation Guide</a> for setup details, or check out the <a href="./demo">Demo</a> for a hands-on example.</p>',31)]))}]]);export{s as __pageData,r as default};
